tools.usage:
string t2string(int t[, string format]);
format: d dd ddd dddd | M MM MMM MMMM | yy yyyy | h hh | m mm | s ss | z zzz | AP ap | U (first char: UTC)
        '...' literal text, '' single quote

tools.example:
int t = time();
string Iso = t2string(t, "Uyyyy-MM-dd hh:mm:ss");      // UTC, ISO-like
string Local = t2string(t, "dddd, d. MMMM yyyy");
board(B) output(filesetext(B.name, ".info"), "wt")
  printf("Board saved: %s\n", t2string(filetime(B.name), "yyyy-MM-dd hh:mm"));

board(B) {
  clrgroup(B);                                  // empty the group
  B.elements(E)
    if (strstr(E.name, "C") == 0) setgroup(E);  // group all capacitors
  }
dlgMessageBox("All capacitors are now in the group.");

string Cmd = "";
board(B) B.elements(E)
  if (ingroup(E)) Cmd += "LOCK " + E.name + ";\n";
if (!Cmd) { dlgMessageBox("!Define a group first (GROUP command)."); exit(1); }
exit(Cmd);

board(B) {
